// =====================================================================
// THE LIBRARY: every Grove practice plus the new ones, in part order.
// Grove practices keep their place in the twelve-week rotation. New
// practices live only here until someone picks one.
// Session 6's site-wide search can read window.GroveLibrary.
// =====================================================================
const LIBRARY = (function(){
  const out = [];
  PARTS.forEach(pt => {
    pt.strands.forEach(sid => {
      const seen = {};
      (PRACTICES[sid] || []).forEach((p, i) => { if (seen[p[0]]) return; seen[p[0]] = 1;
        out.push({ key:'g:'+sid+':'+i, part:pt.id, strand:sid, idx:i, ages:'all', isNew:false,
          name:p[0], text:p[1], busy:p[2], kidName:p[3], kidText:p[4], kidBusy:p[5], how:(HOW[sid] || {})[p[0]] || null }); });
    });
    LIB_NEW.filter(n => n.part === pt.id).forEach(n => out.push(Object.assign({ key:'n:'+n.id, isNew:true }, n)));
  });
  const low = a => a.filter(Boolean).join(' ').replace(/<[^>]+>/g, '').toLowerCase();
  out.forEach(it => { it.findName = low([it.name, it.kidName]); it.findText = low([it.text, it.kidText, PART[it.part].name, PART[it.part].sub, STRAND[it.strand].name]);
    it.find = it.findName + ' ' + it.findText + ' ' + low([(it.how || []).join(' ')]); });
  return out;
})();
const LIB_BY_KEY = Object.fromEntries(LIBRARY.map(it => [it.key, it]));
// Which practices fit which tree. "teen" means middle school and up.
const libFits = (it, age) => it.ages === 'all' || (it.ages === 'teen' ? age !== 'maple' : it.ages === 'teenOnly' ? (age === 'aspen' || age === 'pine') : true);
function libSearch(q, age){
  const words = String(q || '').toLowerCase().split(/\s+/).filter(Boolean);
  const hits = LIBRARY.filter(it => (!age || libFits(it, age)) && words.every(w => it.find.includes(w)));
  if (!words.length) return hits;
  // Strongest matches first: the practice name, then what it says, then the how-to.
  const score = it => words.reduce((n, w) => n + (it.findName.includes(w) ? 3 : it.findText.includes(w) ? 2 : 1), 0);
  return hits.map((it, i) => [it, score(it), i]).sort((a, b) => b[1] - a[1] || a[2] - b[2]).map(x => x[0]);
}
window.GroveLibrary = { items: LIBRARY, get: k => LIB_BY_KEY[k] || null, fits: libFits, search: libSearch };
